  function normalizeTask(source,difficulty,categoryIndex){const variants=['Прочитай заклинание:','На странице Книги появилось задание:','Открой языковую тайну:','Чернильная Тень оставила вопрос:','Восстанови правило:','Хранитель просит ответить:','Руна проверяет знания:','Продолжи путь:'],variant=randomInt(variants.length),answers=shuffle([...source.answers]),correctIndex=answers.findIndex(answer=>normalized(answer)===normalized(source.correct));return{...source,id:source.id,signature:`${source.id}|form-${variant}`,category:source.category,subcategory:source.id.split(':')[1]||`topic-${categoryIndex}`,difficulty,question:`${variants[variant]} ${source.question}`,answers,correctIndex,correct:answers[correctIndex]}}
  function validateTask(candidate){return Boolean(candidate&&candidate.question&&candidate.signature&&candidate.explanation&&candidate.difficulty>=1&&candidate.difficulty<=4&&Array.isArray(candidate.answers)&&candidate.answers.length===3&&new Set(candidate.answers.map(normalized)).size===3&&Number.isInteger(candidate.correctIndex)&&candidate.correctIndex>=0&&candidate.correctIndex<3)}
