  function createCeremonyParticles(legendary=false){const layer=document.querySelector('#ceremony-particles');layer.replaceChildren();const count=legendary?20:14;for(let index=0;index<count;index+=1){const particle=document.createElement('i');particle.textContent=index%4===0?pick(['А','Я','Б','◇']):'';particle.style.setProperty('--particle-x',`${8+Math.random()*84}%`);particle.style.setProperty('--particle-y',`${12+Math.random()*72}%`);particle.style.setProperty('--particle-delay',`${Math.random()*.45}s`);particle.style.setProperty('--particle-drift',`${(Math.random()-.5)*70}px`);layer.append(particle);particle.addEventListener('animationend',()=>particle.remove(),{once:true})}}

  function updateHud() {
    elements.round.textContent = `${round} / ${TOTAL_ROUNDS}`; elements.score.textContent = score.toLocaleString('ru-RU'); elements.runes.textContent = runes; const multiplier = streak >= 5 ? 3 : streak >= 3 ? 2 : 1; elements.combo.textContent = `×${multiplier}`; elements.streak.textContent = streak; elements.freeze.textContent = '∞'; elements.feather.textContent = featherCharges;document.querySelector('.use-feather').disabled=!roundActive||shotPending||featherCharges<1;
    elements.book.style.setProperty('--book-energy', runes / TOTAL_ROUNDS); elements.book.dataset.level = runes >= 10 ? '10' : runes >= 7 ? '7' : runes >= 5 ? '5' : runes >= 3 ? '3' : '0'; elements.bookLetters.textContent = 'АБВГДЕЖЗИК'.slice(0,runes).split('').join(' '); elements.stageName.textContent=stages[Math.min(round-1,9)];elements.currentLevelName.textContent=levels[currentLevel-1].name;
    const baseReveal=[0,.25,.5,.85][currentLevel-1],levelReveal=runes>=10?1:runes>=7?.75:runes>=5?.5:runes>=3?.25:0,reveal=Math.max(baseReveal,levelReveal);elements.guardianSecret.style.setProperty('--reveal',reveal);elements.guardianSecret.classList.toggle('revealed',reveal>0);elements.guardianProgress.textContent=`${Math.round(reveal*100)}%`;elements.bookState.textContent=runes>=10?'Книга полностью пробудилась!':runes>=7?'Страницы сияют живым словом':runes>=5?'Книга начинает открываться':runes>=3?'Появились золотые письмена':runes>0?'На обложке появились слабые письмена':'Книга ждёт свои руны';
    document.body.classList.toggle('final-chapter',round>=8);document.querySelectorAll('.reward-road span').forEach(item=>{const point=Number(item.dataset.milestone);const opened=runes>=point;item.classList.toggle('unlocked',opened);item.querySelector('i').textContent=opened?(point===3?'Золотое перо':point===5?'Тайная страница':point===7?'Амулет':'Большой секрет'):'?'});renderPath();
  }
  function renderPath(){elements.path.replaceChildren();for(let i=0;i<TOTAL_ROUNDS;i+=1){const rune=document.createElement('i');rune.dataset.step=i+1;rune.title=stages[i];rune.className=results[i]===true?'correct':results[i]===false?'missed':i===round-1?'current':'';rune.setAttribute('aria-label',`${i+1}. ${stages[i]}${results[i]===true?': руна найдена':results[i]===false?': пройдено':''}`);elements.path.append(rune)}}

  function flyRune(target){if(!target)return;const from=target.getBoundingClientRect(),to=elements.book.getBoundingClientRect(),rune=document.createElement('i');rune.className='rune-flight';rune.style.left=`${from.left+from.width/2}px`;rune.style.top=`${from.top+from.height/2}px`;rune.style.setProperty('--to-x',`${to.left+to.width/2}px`);rune.style.setProperty('--to-y',`${to.top+to.height/2}px`);document.body.append(rune);setTimeout(()=>{rune.remove();elements.book.classList.remove('book-rune-burst');void elements.book.offsetWidth;elements.book.classList.add('book-rune-burst')},780)}
