  function createTargets() {
    elements.targets.replaceChildren();elements.targets.classList.remove('answered');targetModels=[];const bounds=elements.targets.getBoundingClientRect(),mobile=innerWidth<=700;currentTask.answers.forEach((answer,index)=>{const button=document.createElement('button');button.type='button';button.className='answer-target';button.textContent=answer;button.dataset.answer=answer;button.dataset.answerId=index;button.dataset.targetId=`answer-${currentLevel}-${round}-${index}`;button.setAttribute('aria-label',`Ответ ${index+1}: ${answer}`);elements.targets.append(button);const zoneWidth=mobile?bounds.width:bounds.width/3,zoneHeight=bounds.height/3,baseX=mobile?(bounds.width-button.offsetWidth)/2:index*zoneWidth+(zoneWidth-button.offsetWidth)/2,baseY=mobile?index*zoneHeight+(zoneHeight-button.offsetHeight)/2:bounds.height*.42-button.offsetHeight/2;targetModels.push({element:button,x:baseX,y:baseY,baseX,baseY,vx:(index%2?1:-1)*.055,vy:(index===1?-.045:.04),phase:Math.random()*6.28,frozen:false,rangeX:mobile?10:Math.max(8,zoneWidth/2-button.offsetWidth/2-26),rangeY:mobile?8:42});});
  }
  function proximityFor(model){if(!pointer.active||innerWidth<=700)return 1;const rect=model.element.getBoundingClientRect(),inside=pointer.x>=rect.left-20&&pointer.x<=rect.right+20&&pointer.y>=rect.top-20&&pointer.y<=rect.bottom+20;model.element.classList.toggle('aimed',inside);model.element.classList.remove('near-target');return inside ? .3 : 1}
  function separateTargets(bounds){const hitGap=46;for(let pass=0;pass<2;pass+=1){for(let i=0;i<targetModels.length;i+=1){for(let j=i+1;j<targetModels.length;j+=1){const a=targetModels[i],b=targetModels[j],ax=a.x+a.element.offsetWidth/2,ay=a.y+a.element.offsetHeight/2,bx=b.x+b.element.offsetWidth/2,by=b.y+b.element.offsetHeight/2,dx=bx-ax,dy=by-ay,overlapX=(a.element.offsetWidth+b.element.offsetWidth)/2+hitGap-Math.abs(dx),overlapY=(a.element.offsetHeight+b.element.offsetHeight)/2+hitGap-Math.abs(dy);if(overlapX>0&&overlapY>0){if(overlapX<overlapY){const direction=dx>=0?1:-1;a.x-=direction*overlapX/2;b.x+=direction*overlapX/2;a.vx*=-1;b.vx*=-1}else{const direction=dy>=0?1:-1;a.y-=direction*overlapY/2;b.y+=direction*overlapY/2;a.vy*=-1;b.vy*=-1}}}}}targetModels.forEach(model=>{model.x=Math.max(0,Math.min(model.x,bounds.width-model.element.offsetWidth));model.y=Math.max(0,Math.min(model.y,bounds.height-model.element.offsetHeight))})}
