  function startRound(){roundActive=true;shotPending=false;currentTask=deck[round-1];elements.instruction.textContent=round===10?'ФИНАЛЬНОЕ ИСПЫТАНИЕ':currentTask.instruction;elements.question.textContent=currentTask.question;elements.feedback.classList.remove('show');elements.comboBanner.classList.remove('show');elements.next.hidden=true;document.body.classList.toggle('final-trial',round===10);createTargets();updateHud();cancelAnimationFrame(targetFrame);requestAnimationFrame(animateTargets)}

