  function finishAnswer(correct,target){if(!roundActive)return;roundActive=false;cancelAnimationFrame(targetFrame);targetModels.forEach(model=>model.frozen=true);elements.targets.classList.add('answered');results.push(correct);if(correct){streak+=1;const multiplier=streak>=5?3:streak>=3?2:1;score+=100*multiplier;runes+=1;target?.classList.add('hit-correct');burstLetters(target);const remaining=TOTAL_ROUNDS-round,motivation=remaining===3?' До сундука осталось 3 испытания!':remaining===1?' Последнее испытание перед сундуком!':'';setTimeout(()=>{flyRune(target);showFeedback('РУНА НАЙДЕНА!',`${currentTask.explanation}${motivation}`);showCombo();playSound('correct');playSound('rune')},180)}else{streak=0;target?.classList.add('hit-wrong');const right=[...elements.targets.children].find(item=>normalized(item.dataset.answer)===normalized(currentTask.correct));right?.classList.add('golden-hint');setTimeout(()=>{showFeedback('Почти!',`Правильный ответ: ${currentTask.correct}. ${currentTask.explanation}`);playSound('wrong')},140)}bestCombo=Math.max(bestCombo,streak>=5?3:streak>=3?2:1);updateHud();setTimeout(()=>{elements.next.hidden=false;elements.next.focus()},correct?220:180)}
